<script setup>
import AdminNavigation from '@/Components/Admin/AdminNavigation.vue';import PortalLayout from '@/Layouts/PortalLayout.vue';import{Head,useForm}from'@inertiajs/vue3';import{computed,ref}from'vue';const props=defineProps({roles:Array,permissionGroups:Array,canManageSuperAdmin:Boolean});const selected=ref(props.roles.find(role=>role.name==='admin')||props.roles[0]);const form=useForm({permissions:[...(selected.value?.permissions||[])]});const choose=role=>{selected.value=role;form.permissions=[...role.permissions];form.clearErrors()};const locked=computed(()=>selected.value?.name==='super_admin'&&!props.canManageSuperAdmin);const checked=permission=>form.permissions.includes(permission);const toggle=permission=>{if(locked.value)return;form.permissions=checked(permission)?form.permissions.filter(value=>value!==permission):[...form.permissions,permission]};const toggleGroup=group=>{const all=group.permissions.every(checked);form.permissions=all?form.permissions.filter(value=>!group.permissions.includes(value)):[...new Set([...form.permissions,...group.permissions])]};const save=()=>form.put(route('admin.access-control.update',selected.value.id),{preserveScroll:true,onSuccess:()=>{selected.value.permissions=[...form.permissions]}});const title=value=>value.replaceAll('_',' ').replaceAll('.',' / ').replace(/\b\w/g,c=>c.toUpperCase());
</script>
<template><Head title="Access control"/><PortalLayout area="Administration"><template #navigation><AdminNavigation active="access-control"/></template><div><p class="text-sm font-bold uppercase text-cyan-700">Security</p><h1 class="mt-1 text-3xl font-bold">Access control</h1><p class="mt-2 text-slate-600">Configure what each staff role can view and manage.</p></div><p v-if="$page.props.flash.success" class="success-message mt-5">{{ $page.props.flash.success }}</p><div class="mt-6 flex gap-2 overflow-x-auto border-b border-slate-200"><button v-for="role in roles" :key="role.id" class="whitespace-nowrap border-b-2 px-4 py-3 text-sm font-bold" :class="selected.id===role.id?'border-cyan-600 text-cyan-700':'border-transparent text-slate-500'" @click="choose(role)">{{ title(role.name) }}</button></div><div class="mt-6 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 class="text-2xl font-bold">{{ title(selected.name) }} permissions</h2><p class="mt-1 text-sm text-slate-500">{{ form.permissions.length }} permissions selected</p></div><button class="form-button" :disabled="form.processing||locked" @click="save">Save permissions</button></div><p v-if="locked" class="mt-4 rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm font-semibold text-amber-800">Only a super administrator can change the Super Administrator role.</p><p v-if="form.errors.permissions" class="mt-4 text-sm text-red-600">{{ form.errors.permissions }}</p><div class="mt-6 grid gap-5 lg:grid-cols-2"><section v-for="group in permissionGroups" :key="group.label" class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div class="flex items-center justify-between border-b pb-3"><h3 class="font-bold text-[#0B3D6E]">{{ group.label }}</h3><button type="button" class="text-xs font-bold text-cyan-700 disabled:opacity-40" :disabled="locked" @click="toggleGroup(group)">{{ group.permissions.every(checked)?'Clear group':'Select group' }}</button></div><div class="mt-3 space-y-2"><label v-for="permission in group.permissions" :key="permission" class="flex cursor-pointer items-center gap-3 rounded-xl px-3 py-2.5 hover:bg-slate-50" :class="locked?'cursor-not-allowed opacity-60':''"><input type="checkbox" :checked="checked(permission)" :disabled="locked" @change="toggle(permission)"/><span class="text-sm font-semibold text-slate-700">{{ title(permission) }}</span></label></div></section></div></PortalLayout></template>
